import json
log = []
def ham(a, b):
    return bin(a ^ b).count("1")
def write(a, y):
    for e in log:
        if ham(e[0], a) <= 1:
            e[2] = e[2] / 2
    log.append([a, y, 1.0])
for a, y in [(5, 10), (4, 7), (200, 3), (5, 12)]:
    write(a, y)
best = max((e for e in log if e[0] == 5), key=lambda e: e[2])
print(json.dumps({"weights": [e[2] for e in log], "answer_5": best[1]}))
